function validate([s, k]) {
  if (s.length < 2 || s.length > 50000) return 's needs 2 to 5 * 10^4 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (k < 0 || k > 26) return 'k is between 0 and 26.';
  return null;
}

