function maxSubstringLength(s, k) {
  const n = s.length;
  const first = new Array(26).fill(-1);
  const last = new Array(26).fill(-1);
  for (let i = 0; i < n; i++) {
    const ch = s.charCodeAt(i) - 97;
    if (first[ch] === -1) first[ch] = i;
    last[ch] = i;
  }

  const intervals = [];
  for (let c = 0; c < 26; c++) {
    if (first[c] === -1) continue;
    const start = first[c];
    let end = last[c];
    let valid = true;
    for (let i = start; i <= end; i++) {
      const ch = s.charCodeAt(i) - 97;
      if (first[ch] < start) {
        valid = false;
        break;
      }
      end = Math.max(end, last[ch]);
    }
    if (valid && end - start + 1 < n) {
      intervals.push([start, end]);
    }
  }

  intervals.sort((x, y) => x[1] - y[1]);
  let count = 0;
  let prevEnd = -1;
  for (const [start, end] of intervals) {
    if (start > prevEnd) {
      count++;
      prevEnd = end;
    }
  }
  return count >= k;
}

