function maxSubstringLength(s, k) {
  // Test every substring for being special, then find the most disjoint ones with a DP over prefixes.
  const n = s.length;
  const total = new Array(26).fill(0);
  for (const letter of s) total[letter.charCodeAt(0) - 97]++;
  // most[r] is the largest number of disjoint special substrings inside s[0..r-1].
  const most = new Array(n + 1).fill(0);
  for (let r = 1; r <= n; r++) {
    most[r] = most[r - 1];
    const inside = new Array(26).fill(0);
    for (let l = r - 1; l >= 0; l--) {
      inside[s.charCodeAt(l) - 97]++;
      if (l === 0 && r === n) continue;
      let special = true;
      for (let c = 0; c < 26; c++) if (inside[c] > 0 && inside[c] !== total[c]) special = false;
      if (special) most[r] = Math.max(most[r], most[l] + 1);
    }
  }
  return most[n] >= k;
}

