function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 8000 + Math.floor(rand() * 2001) : 2 + Math.floor(rand() * 11);
  const alphabet = [...'abcdefghijklmnopqrstuvwxyz'];
  for (let i = 25; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [alphabet[i], alphabet[j]] = [alphabet[j], alphabet[i]]; }
  // Segments sit left to right and draw from their own letters. Letters are reused once the pool runs out,
  // which ties distant segments together.
  const pool = large ? 26 : 2 + Math.floor(rand() * 5);
  const segments = large ? 2 + Math.floor(rand() * 23) : 1 + Math.floor(rand() * Math.min(4, n));
  const own = [];
  let next = 0;
  for (let g = 0; g < segments; g++) own.push(Array.from({ length: 1 + Math.floor(rand() * (large ? 2 : 3)) }, () => alphabet[next++ % pool]));
  const chars = [];
  for (let i = 0; i < n; i++) { const letters = own[Math.floor(i * segments / n)]; chars.push(letters[Math.floor(rand() * letters.length)]); }
  // A few stray copies of letters far from home merge segments too.
  const strays = large ? Math.floor(rand() * 4) : rand() < 0.3 ? 1 : 0;
  for (let t = 0; t < strays; t++) chars[Math.floor(rand() * n)] = chars[Math.floor(rand() * n)];
  const s = chars.join('');
  // Count the most disjoint special substrings so that k lands on or just past the answer most of the time.
  const first = {}, last = {};
  for (let i = 0; i < n; i++) { if (!(s[i] in first)) first[s[i]] = i; last[s[i]] = i; }
  const intervals = [];
  for (const letter in first) {
    let start = first[letter], end = last[letter], ok = true;
    for (let i = start; i <= end && ok; i++) { if (first[s[i]] < start) ok = false; else end = Math.max(end, last[s[i]]); }
    if (ok && end - start + 1 < n) intervals.push([start, end]);
  }
  intervals.sort((x, y) => x[1] - y[1]);
  let best = 0, prevEnd = -1;
  for (const [start, end] of intervals) if (start > prevEnd) { best++; prevEnd = end; }
  const roll = rand();
  const k = roll < 0.45 ? best : roll < 0.8 ? Math.min(26, best + 1) : Math.floor(rand() * Math.min(27, best + 4));
  return [s, k];
}
